void test_alloc(void) {
    const char *env = getenv("NUM_ITEMS");
    if (!env) return;               // no user input
    long n = atol(env);
    if (n <= 0) return;             // guard against non-positive
    size_t total = (size_t)n * sizeof(int);
    int *arr = malloc(total);
    arr[n-1] = 0;                    // write at last element
}

void safe_alloc(size_t count) {
    size_t total = count * sizeof(double);
    double *arr = malloc(total);
    arr[count-1] = 3.14;    
    free(arr);
}
